/** omp messages as the JSONL transcript lines the workers parse. */
function transcriptOf(messages: readonly TurnMessage[]): string {
  const lines: string[] = [];
  for (const m of messages) {
    if (m.role === "user") {
      const content =
        typeof m.content === "string"
          ? m.content
