    // lines anyway; emitting them would only pad the file.
    if (m.role !== "assistant" || typeof m.content === "string") continue;
    const content = (m.content ?? []).flatMap((c) =>
      c.type === "text"
        ? [{ type: "text", text: c.text }]
        : c.type === "toolCall"
          ? [{ type: "tool_use", name: c.name }]
          : [],
    );
