  const prompt = [
    typeof input.context === "string" ? input.context : "",
    ...tasks.map((t) => {
      const one = (t ?? {}) as { task?: unknown };
      return typeof one.task === "string" ? one.task : "";
    }),
  ]
    .filter((s) => s.trim() !== "")
    .join("\n\n");
