      const asked = await fire(cmd, dir, full, { STANCE_EMIT_PAYLOAD: "1" });
      if (asked.code !== 0) return undefined;
      const head = asked.stdout.trim();
      // THE ONLY THING THIS PASS ASKS FOR IS THE PAYLOAD ENVELOPE, so any other
      // line is the worker saying it let this fire through with no verdict (no
      // `jq`, no input, a scope it could not read, a re-entry cap already spent)
      // before the judge was ever reached. Dropping it here made every such path
      // silent on omp, whatever the worker printed. Relay it, and judge nothing.
      if (head !== "" && !head.startsWith("{")) {
        relay(head);
        return undefined;
      }
      if (!head.startsWith("{")) return undefined;
      let ask: { rubric?: string; payload?: string };
      try {
        ask = JSON.parse(head);
      } catch {
        return undefined;
      }
      // Nothing emitted ⇒ the worker gated this fire out (not enrolled, nothing
      // judgeable in it). Nothing to judge and nothing to report.
      if (!ask.rubric || !ask.payload) return undefined;
      let rubric: string;
      try {
        rubric = readFileSync(ask.rubric, "utf8");
      } catch {
        return undefined;
      }
      const verdict = await askJudge(ctx, rubric, ask.payload);
      const file = join(dir, "verdict.txt");
      // AN ABSENT VERDICT IS NOT A CLEAN ONE. Returning early on a judge that
      // did not answer is what made a dead endpoint read as approval, turn after
      // turn, in silence — the exact bypass-by-omission the worker's own `dark`
      // exists to refuse. Writing the empty file and firing anyway REACHES that
      // announcement, so the harness inherits the canon's answer rather than
      // re-deciding it here: refuse nothing, and SAY SO.
      writeFileSync(file, verdict ?? "");
      const answered = await fire(cmd, dir, full, { STANCE_VERDICT_FILE: file });
      const out = answered.stdout.trim();
      // A line that is not a verdict is the worker saying this fire went through
      // WITHOUT one: the judge did not answer, the verdict did not parse, a block
      // was discarded, a cap was spent. Every guard notice is relayed, whatever
      // words it opens with, so the operator reads that the guard was not in force.
      // A verdict is JSON and travels through `verdictOf`.
      if (answered.code === 0 && out !== "" && !out.startsWith("{")) {
        relay(out);
        return undefined;
      }
      return verdictOf(answered);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  };
  pi.on("session_stop", async (event, ctx: JudgeContext) => {
    const reason = await judged("sh \"$HOME/.omp/hooks/stance-guardrail/stance-guardrail.sh\"", ctx, { stop_hook_active: event.stop_hook_active === true }, event.messages ?? []);
    if (reason) return { decision: "block", reason };
  });
  // stance-guardrail
  pi.on("tool_result", async (event, ctx: JudgeContext) => {
    if (event.toolName !== "task") return;
    const reason = await judged("sh \"$HOME/.omp/hooks/stance-guardrail/stance-guardrail.sh\"", ctx, {}, dispatchTurn(event));
    if (reason && reason !== lastVerdict) {
      lastVerdict = reason;
      pi.sendUserMessage(reason, { deliverAs: "followUp" });
    }
  });
  // stance-guardrail
  pi.on("tool_call", async (event, ctx: JudgeContext) => {
    if (event.toolName !== "task") return;
    const reason = await judged("sh \"$HOME/.omp/hooks/purview-guardrail/purview-guardrail.sh\"", ctx, { tool_name: "Agent", tool_input: workerInput("Agent", event.input ?? {}) });
    if (reason) return { block: true, reason };
  });
  // purview-guardrail
  pi.on("tool_call", async (event, ctx: JudgeContext) => {
    if (["task"].includes(event.toolName)) return;
    const reason = await judged("sh \"$HOME/.omp/hooks/purview-guardrail/purview-guardrail.sh\"", ctx, toolEnvelope(event));
    if (reason) return { block: true, reason };
  });
  // purview-guardrail
  pi.on("tool_call", async (event, ctx: JudgeContext) => {
    if (event.toolName !== "ask") return;
    const reason = await judged("sh \"$HOME/.omp/hooks/stance-guardrail-pre/stance-guardrail-pre.sh\"", ctx, { tool_name: "AskUserQuestion", tool_input: workerInput("AskUserQuestion", event.input ?? {}) });
    if (reason) return { block: true, reason };
  });
  // stance-guardrail-pre
  pi.on("tool_call", async (event, ctx: JudgeContext) => {
    if (event.toolName !== "task") return;
    const reason = await judged("sh \"$HOME/.omp/hooks/stance-guardrail-pre/stance-guardrail-pre.sh\"", ctx, { tool_name: "Agent", tool_input: workerInput("Agent", event.input ?? {}) });
    if (reason) return { block: true, reason };
  });
  // stance-guardrail-pre
  pi.on("session_start", async (event) => {
    await exec("sh \"$HOME/.omp/hooks/deploy-drift-notice/deploy-drift-notice.sh\"");
  });
  // deploy-drift-notice
  pi.on("before_agent_start", async (event) => {
    await exec("sh \"$HOME/.omp/hooks/deploy-drift-notice/deploy-drift-notice.sh\"");
  });
  // deploy-drift-notice
}

